// pwsh = PowerShell 7+ (falls back to Windows PowerShell); powershell = Windows PowerShell 5.1 (falls back to pwsh).
// One emitter for both; it avoids 7-only syntax (no ?:, ??, &&) so the output also runs on 5.1.
#include "shell.hpp"
#include "emit_dialect.hpp"
#include <set>
namespace {
using namespace forge::script;
std::string pq(const std::string& s) { std::string o = "'"; for (char c : s) { o += c; if (c == '\'') o += '\''; } return o + "'"; }
struct ps_dialect : block_dialect {
    std::set<std::string> need;
    std::string header() override {
        std::string h = "#!/usr/bin/env pwsh\n# generated by `forge script --emit " + cx->target + "`; runs without FORGE (PowerShell 5.1 or 7+)\n";
        if (need.count("env")) h += "function _env($n, $d) { $v = [Environment]::GetEnvironmentVariable($n); if ($null -eq $v) { $d } else { $v } }\n";
        if (need.count("platform")) h += "function _platform { if ($env:OS -eq 'Windows_NT') { 'windows' } elseif ($IsMacOS) { 'macos' } elseif ($IsLinux) { if ($env:ANDROID_ROOT) { 'android' } else { 'linux' } } elseif ((uname -s) -eq 'FreeBSD') { 'freebsd' } else { 'other' } }\n";
        return h;
    }
    std::string var(const std::string& n, bool global) { return global && cx->in_fn ? "$script:" + n : "$" + n; }
    std::string s_lit(const std::string& s) override { return pq(s); }
    std::string ref(const std::string& n, ety, bool g) override { return var(n, g); }
    std::string arith(char op, const std::string& a, const std::string& b) override {
        if (op == '/') return "([long][math]::Truncate(" + a + " / " + b + "))";
        return "(" + a + " " + op + " " + b + ")";
    }
    std::string neg(const std::string& a) override { return "(-" + a + ")"; }
    std::string concat(const std::vector<std::string>& p) override { std::string o = "(''"; for (auto& x : p) o += " + " + x; return o + ")"; }
    std::string i2s(const std::string& i) override { return "([string]" + i + ")"; }
    std::string s2i(const std::string& s) override { return "([long]" + s + ")"; }
    std::string slen(const std::string& s) override { return "([long]([string]" + s + ").Length)"; }
    std::string cmp(const std::string& op, const std::string& a, const std::string& b, bool ints) override {
        static const std::pair<const char*, const char*> io[] = {{"==", "-eq"}, {"!=", "-ne"}, {"<", "-lt"}, {"<=", "-le"}, {">", "-gt"}, {">=", "-ge"}};
        for (auto& [o, t] : io) if (op == o) {
            if (ints) return "(" + a + " " + t + " " + b + ")";
            if (op == "==" || op == "!=") return "(" + a + " -c" + std::string(t + 1) + " " + b + ")";
            return "([string]::CompareOrdinal(" + a + ", " + b + ") " + t + " 0)";
        }
        no("operator " + op);
    }
    std::string c_and(const std::string& a, const std::string& b) override { return "(" + a + " -and " + b + ")"; }
    std::string c_or(const std::string& a, const std::string& b) override { return "(" + a + " -or " + b + ")"; }
    std::string c_not(const std::string& a) override { return "(-not " + a + ")"; }
    std::string c_bool(bool v) override { return v ? "$true" : "$false"; }
    std::string truthy(const std::string& v) override { return "(" + v + " -ceq 'true')"; }
    void let(const std::string& n, const std::string& v, ety t, bool global, bool) override { L(var(n, global) + " = " + (t == ety::Int ? "[long]" + v : v)); }
    void print(const std::string& v, bool nl, bool err) override { L(std::string("[Console]::") + (err ? "Error" : "Out") + ".Write([string]" + v + (nl ? " + \"`n\"" : "") + ")"); }
    void if_(const std::string& c) override { open("if (" + c + ") {"); }
    void else_() override { mid("} else {"); }
    void end_if() override { close("}"); }
    void while_(const std::string& c) override { open("while (" + c + ") {"); }
    void end_while() override { close("}"); }
    void for_(const std::string& v, const std::vector<std::string>& items) override { std::string s; for (auto& i : items) s += (s.empty() ? "" : ", ") + i; open("foreach ($" + v + " in @(" + s + ")) {"); }
    void end_for() override { close("}"); }
    void brk() override { L("break"); }
    void cont() override { L("continue"); }
    void fn_(const std::string& name, const std::vector<std::string>& ps) override {
        std::string s; for (auto& p : ps) s += (s.empty() ? "$" : ", $") + p;
        open("function " + name + "(" + s + ") {");
    }
    void end_fn() override { close("}"); }
    void ret(const std::string& v) override { L(v.empty() ? "return" : "return " + v); }
    std::string call(const std::string& name, const std::vector<std::string>& a, bool want, ety) override {
        std::string s = name; for (auto& x : a) s += " (" + x + ")";
        if (!want) { L("$null = " + s); return ""; }
        return "(" + s + ")";
    }
    void exit_(const std::string& c) override { L("exit " + c); }
    std::string env(const std::string& n, const std::string& d) override { need.insert("env"); return "(_env " + n + " " + d + ")"; }
    void setenv(const std::string& n, const std::string& v) override { L("[Environment]::SetEnvironmentVariable(" + n + ", " + v + ")"); }
    std::string test_path(const std::string& p, char k) override { return std::string("(Test-Path -LiteralPath ") + p + (k == 'd' ? " -PathType Container" : k == 'f' ? " -PathType Leaf" : "") + ")"; }
    void mkdir(const std::string& p) override { L("$null = New-Item -ItemType Directory -Force -Path " + p); }
    void remove(const std::string& p) override { L("Remove-Item -LiteralPath " + p + " -Recurse -Force -ErrorAction SilentlyContinue"); }
    void write(const std::string& p, const std::string& s, bool app) override { L(std::string("[IO.File]::") + (app ? "AppendAllText(" : "WriteAllText(") + p + ", " + s + ")"); }
    std::string read(const std::string& p) override { return "([IO.File]::ReadAllText(" + p + "))"; }
    std::string cwd() override { return "((Get-Location).ProviderPath)"; }
    std::string platform() override { need.insert("platform"); return "(_platform)"; }
    void run(const std::string& cmd, const std::string& o, const std::string& c, bool host) override {
        bool g = !cx->in_fn;
        if (host) {
            L("$global:LASTEXITCODE = 0");
            L(var(o, g) + " = (Invoke-Expression " + cmd + " | Out-String)");
            L(var(c, g) + " = [long]$LASTEXITCODE");
            return;
        }
        // The command travels in an environment variable and the -c script has no double quotes: Windows PowerShell
        // 5.1 (and pwsh's Legacy argument passing) hands embedded '"' to native programs unescaped, so sh lost them.
        // IFS= and set -f keep $_FORGE_SH one unglobbed word; eval restores both before running it.
        L("$env:_FORGE_SH = " + cmd);
        L(var(o, g) + " = (& sh -c 'set -f; IFS=; (eval unset IFS\\; set +f\\; $_FORGE_SH); printf ''\\034%d'' $?') -join \"`n\"");
        L("Remove-Item Env:_FORGE_SH");
        L("$_i = " + var(o, g) + ".LastIndexOf([char]0x1c)");
        L(var(c, g) + " = [long](" + var(o, g) + ".Substring($_i + 1))");
        L(var(o, g) + " = " + var(o, g) + ".Substring(0, $_i)");
    }
    std::string sh_quote(const std::string& v) override { return "(\"'\" + ([string]" + v + ").Replace(\"'\", \"'\\''\") + \"'\")"; }
};
} // namespace
void forge_shell_register_powershell(forge::script::shell_registry& r) {
    auto argv = [](const std::string& exe, const std::string& sc) -> std::vector<std::string> { return {exe, "-NoProfile", "-NonInteractive", "-Command", sc}; };
    forge::script::shell_backend p; p.name = "pwsh"; p.aliases = {"ps"}; p.exes = {"pwsh", "powershell"}; p.family = "powershell"; p.golden_tested = true; p.argv = argv; p.quote = pq;
    p.emitter = [] { return std::make_unique<ps_dialect>(); }; p.emit_ext = ".ps1"; p.emit_tested = true;
    r.add(p);
    forge::script::shell_backend w; w.name = "powershell"; w.aliases = {"powershell5", "winps"}; w.exes = {"powershell", "pwsh"}; w.family = "powershell"; w.argv = argv; w.quote = pq;
    w.notes = "Windows PowerShell 5.1 (Windows only; tested via the pwsh fallback elsewhere)";
    w.emitter = p.emitter; w.emit_ext = ".ps1";
    r.add(w);
}
